#include <string>
std::string bracketed(const std::string& value) {
    return "[" + value + "]";
}

#include <string>
bool has_csv_suffix(const std::string& name) {
    return name.substr(name.size() - 4) == ".csv";
}

#include <string>
std::string parenthesized(const std::string& value) {
    return "(" + value + ")";
}
